using System.Text.Json;
namespace FacialPresets;
// Reject omitted authored values before deserialization can synthesize defaults.
public static class JsonShape {
 static bool Optional(JsonElement e,string name,out JsonElement value){if(e.ValueKind!=JsonValueKind.Object)throw new InvalidDataException("표정 목록이 잘못되었습니다.");value=default;int count=0;foreach(var p in e.EnumerateObject())if(p.Name.Equals(name,StringComparison.OrdinalIgnoreCase)){value=p.Value;count++;}if(count>1)throw new InvalidDataException("필수 필드가 없는 프리셋입니다.");return count==1;}
 static JsonElement Required(JsonElement e,string name,string error){if(!Optional(e,name,out var value))throw new InvalidDataException(error);return value;}
 public static void Preset(JsonElement p){const string error="필수 필드가 없는 프리셋입니다.";foreach(var n in new[]{"schemaVersion","id","name","profile"})Required(p,n,error);var channels=Required(p,"channels",error);if(channels.ValueKind!=JsonValueKind.Object)throw new InvalidDataException(error);var names=new HashSet<string>();foreach(var c in channels.EnumerateObject()){if(!names.Add(c.Name))throw new InvalidDataException(error);var morphs=Required(c.Value,"morphs",error);if(morphs.ValueKind!=JsonValueKind.Array)throw new InvalidDataException(error);foreach(var m in morphs.EnumerateArray()){foreach(var n in new[]{"backend","id","name","strength"})Required(m,n,error);if(Optional(m,"enabled",out var enabled)&&enabled.ValueKind is not (JsonValueKind.True or JsonValueKind.False))throw new InvalidDataException(error);}}}
 public static void Clip(JsonElement c){const string error="클립 필수 필드가 없습니다.";foreach(var n in new[]{"schemaVersion","id","name","profile","duration"})Required(c,n,error);var keys=Required(c,"keys",error);if(keys.ValueKind!=JsonValueKind.Array)throw new InvalidDataException(error);foreach(var k in keys.EnumerateArray()){foreach(var n in new[]{"id","time","interpolation"})Required(k,n,error);Preset(Required(k,"state",error));}}
 public static void ProjectFacials(JsonElement project){if(!Optional(project,"FacialTracks",out var tracks))return;if(tracks.ValueKind!=JsonValueKind.Array)throw new InvalidDataException("표정 목록이 잘못되었습니다.");foreach(var item in tracks.EnumerateArray()){if(Optional(item,"Clip",out var clip)&&clip.ValueKind!=JsonValueKind.Null)Clip(clip);else Preset(Required(item,"preset","필수 필드가 없는 프리셋입니다."));}}
}
